async function updateCompanyInMemory(company) {
  try {
    if (!company.id) {
      throw new Error('Company ID is required for updates');
    }

    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'updateCompany',
        company: company
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to update company');
    }

    return {
      success: true,
      companyId: company.id,
      message: `Company '${company.name || company.id}' updated successfully`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
